		local npc_spec = {}
		for i = 1, #data do
			npc_spec[spec_name .. i] = spec_name
		end

		local dynamic_npc = load_util.create_dynamic_npcs_async(npc_spec)
		table.insert(self.dynamic_npcs, dynamic_npc)

		for i = 1, #data do
			local npc = dynamic_npc[spec_name .. i]
			local current_data = data[i]
			npc.Position = current_data.pos
			scene_util.set_direction(npc, current_data.dir, false)
			scene_util.set_emotion(npc, self, current_data.emotion)
			scene_util.set_anim(npc, self, { name = current_data.anim, sfx_name = false, one_shot_sfx = false })
		end
	end
end

function local_class:dispose_audience()
	if not self.dynamic_npcs then
		return
	end

	for i = 1, #self.dynamic_npcs do
		load_util.dispose_dynamic_npcs(self.dynamic_npcs[i])
		self.dynamic_npcs[i] = nil
	end
end

return local_class

