local controller_base = get_or_create_global_variable('Quest/Base/QuestControllerBase')

---@class WaterWorldCompanionBoyController : QuestControllerBase
local local_class = newclass('WaterWorldCompanionBoyController', controller_base)

function local_class:init(cs_controller)
	self.super:init(cs_controller)

	-- 사용할 섹션 스크립트 정보. 주석 해제하고 사용
	self.script_config = {
		HasPreSection = false,
		NormalSectionCount = 1,
		HasPostSection = false
	}

	-- 퀘스트 ID
	self.quest_id = 468

	self.field_object = metatable_helper.inherit({
		spec = {
			emblem = 's13_companion_boy_emblem',
		}
	}, function(this, key)
		return get_field_object(this.spec[key])
	end)

	self.marker = metatable_helper.inherit({
		spec = {
			power_station_pos = 's13_companion_boy_power_station_pos',
		}
	}, function(this, key)
		return field_util.get_marker_pos(this.spec[key])
	end)

	self.fx = metatable_helper.create_fx_accessor({
		symbol = function()
			return unity_object_pool.GetOrCreate('fx_ww_companion_symbol')
		end,
	})

	self.cashed_fx_list = {
		cached_inst = {},

		cache = function(this, fx)
			if this.cached_inst == nil then
				this.cached_inst = {}
			end

			table.insert(this.cached_inst, fx)
		end,

		dispose = function(this, clear_inst)
			for i = 1, #this.cached_inst do
				this.cached_inst[i]:Dispose()
				this.cached_inst[i] = nil
			end

			if clear_inst then
				this.cached_inst = nil
			end
		end
	}
end

function local_class:load_resource()
	self.fx:load_async()
end

function local_class:dispose()
	self.cashed_fx_list:dispose(true)
	self.cashed_fx_list = nil

	self.super:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
	local main_quest = user_progress:GetStartedQuest(self.quest_id)

	if main_quest ~= nil then
		if main_quest.IsComplete then
			local power_station_pos = self.marker.power_station_pos

			self.cashed_fx_list:cache(self.fx:symbol():Instantiate(power_station_pos + vector(0, 0.5, 0)))
			self.field_object.emblem.Position = power_station_pos
		end
	end
end

function local_class:on_stage_end()
end

return local_class

